fn tally(xs: List[Int], x: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, x))
  effects pure
  example (tally([1, 2, 2, 3], 2) == 2)
  example (tally([], 5) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then (1 + tally(t, x)) else tally(t, x) }
}

fn pick(whole: List[Int], xs: List[Int], cand: Int) -> Int
  requires (len(xs) >= 0)
  ensures forall x in xs: (count(whole, x) <= count(whole, result))
  ensures (count(whole, result) >= count(whole, cand))
  effects pure
  example (pick([1, 2, 2, 3], [1, 2, 2, 3], 1) == 2)
  example (pick([5, 5, 1], [5, 5, 1], 5) == 5)
{
  match xs { [] => cand [h, ..t] => if (tally(whole, h) > tally(whole, cand)) then pick(whole, t, h) else pick(whole, t, cand) }
}

fn top(xs: List[Int]) -> Int
  requires (len(xs) >= 1)
  ensures contains(xs, result)
  ensures forall x in xs: (count(xs, x) <= count(xs, result))
  effects pure
  example (top([1, 2, 2, 3]) == 2)
  example (top([7]) == 7)
{
  match xs { [] => 0 [h, ..t] => pick(xs, xs, h) }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures (((len(xs) == 0) and (result == None)) or ((len(xs) > 0) and (result == Some(top(xs)))))
  effects pure
  example (most_frequent([1, 2, 2, 3]) == Some(2))
  example (most_frequent([]) == None)
  example (most_frequent([5, 5, 1]) == Some(5))
{
  match xs { [] => None [h, ..t] => Some(top(xs)) }
}

