  ensures match result { None => not (exists k in 0..len(xs): (k == i)) Some(v) => ((i < len(xs)) and (v == xs[i])) }
  effects pure
  example (nth([5, 6, 7], 1) == Some(6))
  example (nth([5, 6, 7], 3) == None)
  example (nth([], 0) == None)
  example (nth([5, 6, 7], 0) == Some(5))
{
  match xs { [] => None [h, ..t] => if (i == 0) then Some(h) else nth((i - 1), t) }
}

